import{clone,clamp,elevationAt,inside,distanceSegment,simplify}from'./model.js?v=6';
import{Heap,center,distance,mix,lineSamples}from'./landscape-hydrology.js?v=1';
function lakeDistance(p,l){return inside(p,l.points)?0:Math.min(...l.points.map((q,i)=>distanceSegment(p,q,l.points[(i+1)%l.points.length])));}
export function addEstates(doc,field){let lakes=doc.features.filter(f=>f.type==='lake'),specs=[{id:'estate-tingsong',name:'听松山庄',aim:[3.9,4.55],bounds:[2.8,4.25,4.9,5.5]},{id:'estate-qinglan',name:'晴岚山庄',aim:[11.5,4.0],bounds:[10.5,3.4,12.5,4.55],lake:doc.features.find(f=>f.id==='lake-east')}];for(let s of specs){if(doc.features.some(f=>f.id===s.id))continue;let best=null,score=Infinity;for(let y=s.bounds[1];y<s.bounds[3];y+=.05)for(let x=s.bounds[0];x<s.bounds[2];x+=.05){let p=[x,y],h=elevationAt(field,x,y),slope=Math.hypot(elevationAt(field,x+.05,y)-elevationAt(field,x-.05,y),elevationAt(field,x,y+.05)-elevationAt(field,x,y-.05))/100;if(lakes.some(l=>lakeDistance(p,l)<.12))continue;if(s.lake&&(lakeDistance(p,s.lake)>.6||y>center(s.lake)[1]))continue;let c=distance(p,s.aim)+slope*2+Math.max(0,h-3500)/400;if(c<score){score=c;best={p,h};}}if(!best)throw Error('山庄选址未找到适合的湖岸陆地。');doc.features.push({id:s.id,type:'village',placeKind:'lodge',name:s.name,points:[best.p],closed:false,elevation:Math.round(best.h),terrainConstraint:'none'});}}
export function trailStats(field,points){let ps=lineSamples(points,.02),up=0,down=0,length=0,grades=[];for(let i=1;i<ps.length;i++){let d=distance(ps[i-1],ps[i])*1000,dh=elevationAt(field,...ps[i])-elevationAt(field,...ps[i-1]);if(d<.01)continue;up+=Math.max(0,dh);down+=Math.max(0,-dh);length+=d;grades.push(Math.abs(dh)/d);}grades.sort((a,b)=>a-b);return{lengthKm:length/1000,ascentMetres:up,descentMetres:down,p95Grade:grades[Math.floor(grades.length*.95)]||0,maxGrade:grades.at(-1)||0};}
export function developTrails(doc,field){
 const nx=401,ny=321,N=nx*ny,step=.05,point=k=>[k%nx*step,Math.floor(k/nx)*step],key=p=>Math.round(p[1]*20)*nx+Math.round(p[0]*20),lakes=doc.features.filter(f=>f.type==='lake'),water=new Uint8Array(N),heights=new Float64Array(N),slope=new Float32Array(N),coast=new Float32Array(N);
 for(let k=0;k<N;k++){let[x,y]=point(k);heights[k]=elevationAt(field,x,y);slope[k]=Math.hypot(elevationAt(field,x+.1,y)-elevationAt(field,x-.1,y),elevationAt(field,x,y+.1)-elevationAt(field,x,y-.1))/200;water[k]=lakes.some(l=>inside([x,y],l.points))?1:0;}
 let shoreMask=water.slice();for(let k=0;k<N;k++)if(shoreMask[k]){let x=k%nx,y=Math.floor(k/nx);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if(x+dx>=0&&x+dx<nx&&y+dy>=0&&y+dy<ny)water[(y+dy)*nx+x+dx]=1;}
 const targets=[];for(let f of doc.features){if(f.type==='village'||f.type==='lake'||f.type==='waterfall'||f.constraint==='saddle'||f.functionalArea||f.landscapeDestination){let desired=f.type==='waterfall'?f.points[1]:center(f),best=-1,bestScore=Infinity;
  for(let k=0;k<N;k++){if(water[k])continue;let p=point(k),d=distance(p,desired);if(f.type==='lake'){let shore=lakeDistance(p,f);if(shore<.07||shore>.30)continue;d=shore+distance(p,desired)*.03;}else if(f.type==='forest'||f.type==='grassland'||f.type==='meadow'){if(!inside(p,f.points)||f.holes?.some(h=>inside(p,h)))continue;}else if(d>.25)continue;let score=d+slope[k]*.12;if(score<bestScore){bestScore=score;best=k;}}
  if(best>=0)targets.push({id:f.id,name:f.name,kind:f.type,key:best,point:point(best),feature:f});
 }}
 const root=targets.find(t=>t.id==='village-nw')||targets[0],cost=new Float64Array(N).fill(Infinity),parent=new Int32Array(N).fill(-1),done=new Uint8Array(N),heap=new Heap(),dirs=[];
 // More bearings on steep hillsides let the search traverse contours instead
 // of forcing the trail into the eight directions of a square raster.
 for(let dy=-4;dy<=4;dy++)for(let dx=-4;dx<=4;dx++){if(!dx&&!dy)continue;let gcd=(a,b)=>b?gcd(b,a%b):a;if(gcd(Math.abs(dx),Math.abs(dy))!==1)continue;dirs.push([dx,dy,Math.hypot(dx,dy)*50]);}
 const passes=doc.features.filter(f=>f.constraint==='saddle'),passZone=new Uint8Array(N);for(let k=0;k<N;k++){let p=point(k);passZone[k]=passes.some(f=>distance(p,f.points[0])<.35)?1:0;}let cached=new Float32Array(N*dirs.length);
 const expand=()=>{while(heap.length){let[k,c]=heap.pop();if(c>cost[k]+1e-5)continue;let x=k%nx,y=Math.floor(k/nx),a=point(k);for(let z=0;z<dirs.length;z++){let[dx,dy,metres]=dirs[z],xx=x+dx,yy=y+dy;if(xx<0||xx>=nx||yy<0||yy>=ny)continue;let q=yy*nx+xx;if(water[q])continue;let edge=cached[k*dirs.length+z];if(!edge){let b=point(q),dh=heights[q]-heights[k],grade=Math.abs(dh)/metres,blocked=false,peakGrade=grade,n=Math.max(2,Math.ceil(metres/25)),lastH=heights[k];for(let n1=1;n1<=n;n1++){let t=n1/n,p=mix(a,b,t),kk=key(p);if(water[kk]){blocked=true;break;}let h=elevationAt(field,...p);peakGrade=Math.max(peakGrade,Math.abs(h-lastH)/(metres/n));lastH=h;}if(blocked||peakGrade>((passZone[k]||passZone[q])?.85:.42))edge=Infinity;else edge=metres*(1+6*(grade/.12)**3+3*(peakGrade/.18)**4+.7*Math.max(0,slope[q]-.55)**2)+Math.max(0,dh)*4;cached[k*dirs.length+z]=edge;}let cc=c+edge;if(cc<cost[q]){cost[q]=cc;parent[q]=k;heap.push(q,cc);}}}};
 cost[root.key]=0;heap.push(root.key,0);expand();
 let existing=new Set([root.key]),edges=[],records=[],remaining=targets.filter(t=>t!==root);root.feature.accessPoint=root.point;
 while(remaining.length){remaining.sort((a,b)=>cost[a.key]-cost[b.key]);let t=remaining.shift();if(!Number.isFinite(cost[t.key]))throw Error('步道无法连接 '+t.name);let cells=[],k=t.key;while(k>=0&&!existing.has(k)){cells.push(k);k=parent[k];}if(k>=0)cells.push(k);for(let q of cells)existing.add(q);if(cells.length<2){t.feature.accessPoint=t.point;records.push({featureId:t.id,sharedNetwork:true});continue;}let ps=cells.map(point),f={id:'terrain-trail-'+edges.length,type:'trail',name:t.name+'支径',closed:false,points:ps,flowGeometry:'sampled',connectsTo:t.id,routeRole:t.feature.constraint==='saddle'?'pass-approach':'contour-traverse',stats:trailStats(field,ps)};edges.push(f);t.feature.accessPoint=t.point;t.feature.accessibleVia=f.id;records.push({featureId:t.id,trailId:f.id});for(let q of cells){cost[q]=0;parent[q]=-1;heap.push(q,0);}expand();}
 let old=doc.features.filter(f=>f.type==='trail');for(let i=0;i<Math.min(old.length,edges.length);i++){let oldId=edges[i].id;edges[i].id=old[i].id;edges[i].name=old[i].name;for(let r of records)if(r.trailId===oldId)r.trailId=edges[i].id;for(let t of targets)if(t.feature.accessibleVia===oldId)t.feature.accessibleVia=edges[i].id;}
 doc.features=[...doc.features.filter(f=>f.type!=='trail'),...edges];doc.trailNetwork={version:1,root:root.id,spacingMetres:50,targetCount:targets.length,targets:targets.map(({id,name,kind,point})=>({id,name,kind,point})),links:records,routeMethod:'terrain-cost tree: cubic grade penalty, contour-bearing traverses, water exclusion; no lake crossings',lengthKm:edges.reduce((s,f)=>s+f.stats.lengthKm,0),preferredGrade:.12,designStatus:'virtual terrain planning; steep pass approaches need later detailed tread design'};return doc.trailNetwork;
}
